import {parseCandles,research,clock} from './engine.mjs';
let report=null,error='',datasetIndex=0,model='B',focus=0,marketBars=[],verification='',busy=false;
const cache=new Map();let rerender=()=>{},notify=()=>{};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const usd=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n),price=n=>Number.isFinite(n)?n.toFixed(2):'—';
const time=t=>clock(t).hm+' ET',stamp=t=>clock(t).day+' '+time(t);
const hash=async text=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(text)))).map(x=>x.toString(16).padStart(2,'0')).join('');
const current=()=>report?.datasets[datasetIndex],run=()=>current()?.runs.find(r=>r.result.cfg.setup===model),sig=()=>run()?.result.signals[focus];
async function data(){const d=current();if(cache.has(d.id)){marketBars=cache.get(d.id);return marketBars;}const r=await fetch(d.csvPath,{cache:'no-store'});if(!r.ok)throw Error('Historical candles could not be loaded.');const text=await r.text();if(await hash(text)!==d.csvSha256)throw Error('Historical data checksum mismatch; rerun blocked.');const parsed=parseCandles(text);cache.set(d.id,parsed);if(current().id===d.id)marketBars=parsed;return parsed;}
export async function loadEvidence(render,toast){rerender=render;notify=toast;try{const r=await fetch('evidence/report.json',{cache:'no-store'});if(!r.ok)throw Error('The saved research report is unavailable.');report=await r.json();await data();}catch(e){error=e.message;}rerender();}
function reviewChart(){const s=sig();if(!s)return '<div class="empty">No candidate was detected for this model and session.</div>';if(!marketBars.length)return '<div class="empty">Loading historical candles…</div>';const t=run().result.trades.find(t=>t.signalTime===s.t),center=s.t+60000,bs=marketBars.filter(b=>b.t>=center-20*60000&&b.t<=Math.max(center+12*60000,t?t.exitTime+3*60000:center));if(!bs.length)return '';const w=900,h=290,left=14,right=83,top=25,bottom=30,values=bs.flatMap(b=>[b.h,b.l]);for(const x of [s.entry,s.stop,s.target])if(Number.isFinite(x))values.push(x);const hi=Math.max(...values),lo=Math.min(...values),span=hi-lo||1,dx=(w-left-right)/bs.length,y=v=>top+(hi-v)/span*(h-top-bottom),x=ts=>left+(ts-bs[0].t)/60000*dx+dx/2;let out=`<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Historical one-minute MNQ candles surrounding the selected signal with modeled entry, stop and target">`;
for(let i=0;i<5;i++){const v=hi-span*i/4;out+=`<path d="M${left} ${y(v)}H${w-right}" stroke="#e6ebdf"/><text x="${w-right+9}" y="${y(v)+3}" fill="#8b9980" font-size="9">${v.toFixed(2)}</text>`;}
if(s.gap){const low=y(s.gap.hi),high=y(s.gap.lo);out+=`<rect x="${left}" y="${low}" width="${w-left-right}" height="${Math.max(1,high-low)}" fill="#dbe5c9" opacity=".55"/><text x="${left+8}" y="${low+11}" fill="#82936c" font-size="8">SIGNAL GAP ${price(s.gap.lo)}–${price(s.gap.hi)}</text>`;}
for(const b of bs){const cx=x(b.t),c=b.c>=b.o?'#aebf96':'#365b41';out+=`<line x1="${cx}" x2="${cx}" y1="${y(b.h)}" y2="${y(b.l)}" stroke="${c}"/><rect x="${cx-dx*.25}" y="${y(Math.max(b.o,b.c))}" width="${Math.max(2,dx*.5)}" height="${Math.max(1,Math.abs(y(b.c)-y(b.o)))}" fill="${c}"/>`;}
for(const [label,value,color] of [['ENTRY',s.entry,'#477957'],['STOP',s.stop,'#b06b5b'],['TARGET',s.target,'#6e8a43']])if(Number.isFinite(value))out+=`<path d="M${left} ${y(value)}H${w-right}" stroke="${color}" stroke-dasharray="5 4"/><text x="${left+8}" y="${y(value)-5}" fill="${color}" font-size="8">${label} ${price(value)}${!t?' · NOT FILLED':''}</text>`;
const sx=x(center);out+=`<path d="M${sx} ${top}V${h-bottom}" stroke="#738c60" stroke-dasharray="3 4"/><text x="${Math.min(w-200,Math.max(20,sx+5))}" y="15" fill="#526f44" font-size="9">CONFIRMED ${time(center)}</text>`;if(t){out+=`<circle cx="${x(t.entryTime)}" cy="${y(t.entry)}" r="4" fill="#356443" stroke="white"/><circle cx="${x(t.exitTime)}" cy="${y(t.exit)}" r="4" fill="#b47c3c" stroke="white"/>`;}
for(let i=0;i<bs.length;i+=Math.max(1,Math.floor(bs.length/6)))out+=`<text x="${x(bs[i].t)-13}" y="${h-9}" fill="#8e9d80" font-size="9">${clock(bs[i].t).hm}</text>`;return out+'</svg>';}
export function evidencePanel(){if(!report)return `<section class="panel evidence-panel"><h2>Historical market evidence</h2><p>${error?esc(error):'Loading saved historical research…'}</p></section>`;const d=current(),r=run().result,s=sig(),t=s?r.trades.find(t=>t.signalTime===s.t):null;return `<section class="panel evidence-panel" id="marketEvidence"><div class="panel-heading"><div><div class="eyebrow">REAL PRICE HISTORY / SIMULATED EXECUTION</div><h2 style="font-size:22px;margin-top:9px">Historical backtest evidence</h2><p>Saved runs on actual vendor-supplied MNQ prices. Every candidate, rejection, and modeled fill is inspectable.</p></div><span class="tag">RULES ENGINE v1.1</span></div><div class="notice evidence-note"><strong>This is a fixed-R rules-based research test, not trained-AI performance or broker executions.</strong> Targets use 2R because the trader’s liquidity selection has not been fully defined. A++ profitability has not been tested.</div><div class="evidence-select"><label>Historical session<select id="proofDataset">${report.datasets.map((x,i)=>`<option value="${i}" ${datasetIndex===i?'selected':''}>${x.date} · ${esc(x.symbol)} · ${esc(x.kind)}</option>`).join('')}</select></label><label>Strategy model<select id="proofModel"><option value="A" ${model==='A'?'selected':''}>A+ / Five-minute inversion</option><option value="B" ${model==='B'?'selected':''}>B / One-minute continuation</option></select></label><button class="button primary" id="proofRerun" ${busy?'disabled':''}>${busy?'Replaying…':'↻ Reproduce this run'}</button></div><div class="evidence-status" role="status">${esc(verification||'Saved result · original rules retained · no parameter optimization')} ${error?`<span class="error">${esc(error)}</span>`:''}</div><div class="metrics evidence-metrics">${[['Net simulated P&L',usd(r.net)],['Executed / detected',r.trades.length+' / '+r.signals.length],['Wins / losses',r.trades.filter(t=>t.pnl>0).length+' / '+r.trades.filter(t=>t.pnl<0).length],['Closed-trade drawdown',usd(r.maxDrawdown)]].map(([k,v])=>`<div class="metric"><div class="metric-top">${k}</div><div class="metric-value">${v}</div></div>`).join('')}</div><div class="source-audit"><div><small>DATA SOURCE</small><a href="${esc(d.url)}" target="_blank" rel="noopener">${esc(d.name)} ↗</a></div><div><small>INPUT CANDLES</small><b>${d.rows.toLocaleString()} · 1 minute</b></div><div><small>09:30–16:00 ET COVERAGE</small><b>${d.rthBars} / 391 timestamps</b></div><div><small>ENTRY WINDOW</small><b>09:30–11:30 New York</b></div></div><div class="section-header"><h3>Inspect the market evidence</h3><span class="tag gray">${r.signals.length} CANDIDATES</span></div>${r.signals.length?`<label>Signal confirmed at<select id="proofSignal">${r.signals.map((x,i)=>`<option value="${i}" ${focus===i?'selected':''}>${time(x.t+60000)} · ${x.status}${x.rejection?' · '+esc(x.rejection):''}</option>`).join('')}</select></label>`:''}<div class="evidence-chart">${reviewChart()}</div>${s?`<div class="two-cols"><div><h3>${t?'Simulated trade':'Rejected signal'}</h3><p>${t?`Confirmed ${time(s.t+60000)} → entry ${time(t.entryTime)} → exit ${time(t.exitTime)}. ${t.qty} MNQ · ${t.reason} · <strong class="${t.pnl>=0?'positive':'negative'}">${usd(t.pnl)} net</strong>.`:`${esc(s.rejection||s.status)}. No order was simulated; displayed price levels are hypothetical.`}</p><p>Signal gap: ${price(s.gap.lo)}–${price(s.gap.hi)}. ${s.contextEvidence?`15m context gap: ${price(s.contextEvidence.lo)}–${price(s.contextEvidence.hi)}, touched ${time(s.contextEvidence.touchedAt)}.`:'No qualifying 15m context recorded.'}</p></div><ul class="checklist evidence-checklist">${s.checks.map(c=>`<li class="${c.pass?'pass':'fail'}">${esc(c.label)}</li>`).join('')}</ul></div>`:''}<details><summary>All saved runs — including losses and no-trade sessions</summary><div class="table-wrap"><table><thead><tr><th>Date / source</th><th>Model</th><th>Signals</th><th>Trades</th><th>Net result</th><th>Win rate</th></tr></thead><tbody>${report.datasets.flatMap(x=>x.runs.map(a=>`<tr><td>${x.date} · ${esc(x.symbol)}</td><td>${a.result.cfg.setup==='A'?'A+ inversion':'B continuation'}</td><td>${a.result.signals.length}</td><td>${a.result.trades.length}</td><td class="${a.result.net<0?'negative':'positive'}">${usd(a.result.net)}</td><td>${a.result.trades.length?a.result.winRate.toFixed(1)+'%':'—'}</td></tr>`)).join('')}</tbody></table></div><p>Models are separate experiments. Do not add them as if they were one portfolio. A 100% win rate on two trades does not establish an edge.</p></details><details><summary>Data provenance, checksums & reproducibility</summary><p>${esc(d.method)}</p><p>Observed time range: ${stamp(d.start)} → ${stamp(d.end)}. Validation: ascending timestamps, no duplicates, valid OHLC, 0.25 tick grid, and contiguous regular-session minute timestamps. Coverage checks do not prove exchange feed completeness.</p><p><strong>Source SHA-256</strong><br><code class="hash">${d.rawSha256}</code></p><p><strong>Input CSV SHA-256</strong><br><code class="hash">${d.csvSha256}</code></p><p><strong>Engine SHA-256</strong><br><code class="hash">${report.engineSha256}</code></p><p>Source retrieved ${esc(d.retrievedAt)}. Report built ${esc(report.createdAt)}. “Reproduce this run” checks the CSV and engine hashes, reruns the saved configuration, and compares every recorded trade, signal, and metric. This proves reproducibility of this implementation, not trading profitability.</p><div class="actions"><a class="button small" href="${esc(d.csvPath)}" download>↓ Download source candles</a><a class="button small" href="evidence/report.json" download>↓ Full audit report</a><a class="button small" href="engine.mjs" download>↓ Engine source</a></div></details><details><summary>Exact assumptions & limits of this evidence</summary><ul>${report.assumptions.map(t=>`<li>${esc(t)}</li>`).join('')}</ul><h3>What this does not establish</h3><ul>${report.limitations.map(t=>`<li>${esc(t)}</li>`).join('')}</ul><p>${esc(report.selection)}</p><p>${esc(report.ruleChanges)}</p></details><div class="actions" style="margin-top:20px"><button class="button" id="proofLoad">Load this run into the editable research lab ↗</button><span class="muted" style="font-size:10px;align-self:center">Saved evidence stays fixed when research settings change.</span></div></section>`;}
export function bindEvidence(load){document.getElementById('proofDataset')?.addEventListener('change',async e=>{datasetIndex=+e.target.value;focus=0;marketBars=[];error='';verification='';rerender();try{await data();}catch(e){error=e.message;}rerender();});document.getElementById('proofModel')?.addEventListener('change',e=>{model=e.target.value;focus=0;verification='';rerender();});document.getElementById('proofSignal')?.addEventListener('change',e=>{focus=+e.target.value;rerender();});document.getElementById('proofRerun')?.addEventListener('click',async()=>{busy=true;error='';verification='Checking inputs and rerunning saved rules…';rerender();try{const response=await fetch('engine.mjs',{cache:'no-store'});if(!response.ok||await hash(await response.text())!==report.engineSha256)throw Error('Engine checksum mismatch; saved result cannot be reproduced with this version.');const bs=await data(),actual=research(bs,run().result.cfg);if(JSON.stringify(actual)!==JSON.stringify(run().result))throw Error('Recomputed results differ from the saved snapshot.');verification='✓ Reproduced exactly: CSV hash, engine hash, all signals, trades, and metrics match.';notify('Historical run reproduced exactly');}catch(e){error=e.message;verification='Verification failed';}busy=false;rerender();});document.getElementById('proofLoad')?.addEventListener('click',async()=>{try{const bs=await data();load(bs,run().result.cfg,current().name+' · '+current().date);notify('Historical run loaded. Editable settings are separate from the saved evidence.');}catch(e){notify(e.message)}});}
